INSERT INTO _r VALUES
 ('ENT_NORF_DRAUGR','member_of','ENT_NORF_FOLK_BEINGS','high','Draugr is one of the lesser folkloric supernatural classes collected under the hub.'),
 ('ENT_NORF_LANDVAETTIR','member_of','ENT_NORF_FOLK_BEINGS','high','Landvaettir are a folkloric supernatural class under the hub.'),
 ('ENT_NORF_FYLGJA','member_of','ENT_NORF_FOLK_BEINGS','high','Fylgja is a folkloric supernatural class under the hub.'),
 ('ENT_NORF_DISIR','member_of','ENT_NORF_FOLK_BEINGS','high','Disir are a folkloric supernatural class under the hub.'),
 ('ENT_NORF_HULDRA','member_of','ENT_NORF_FOLK_BEINGS','high','Huldra is a folkloric supernatural class under the hub.'),
 ('ENT_NORF_NISSE','member_of','ENT_NORF_FOLK_BEINGS','high','Nisse/tomte is a folkloric supernatural class under the hub.'),
 ('ENT_NORF_MARA','member_of','ENT_NORF_FOLK_BEINGS','high','Mara is a folkloric supernatural class under the hub.'),
 ('ENT_NORF_NOKK','member_of','ENT_NORF_FOLK_BEINGS','high','Nokk/nacken is a folkloric supernatural class under the hub.'),
 ('ENT_NORF_TROLL','member_of','ENT_NORF_FOLK_BEINGS','high','Troll (as folklore class) is collected under the hub.'),
 ('ENT_NORF_TROLL','aligned_with','ENT_NOR_JOTNAR','high','The folklore troll-class is historically continuous with the eddic jotnar/thurses; saga usage often calls jotnar ''troll''. Aligned (functional/continuity) rather than equated, since the folklore class is distinct from the mythological jotnar collective.'),
 ('ENT_NORF_MARA','aligned_with','ENT_VF_OLD_HAG','high','The Norse mara (the spirit that ''rides'' the sleeper) is the etymological and phenomenological root of the contemporary sleep-paralysis Old Hag tradition; modern functional cognate, so aligned_with.'),
 ('ENT_NORF_FYLGJA','aligned_with','ENT_NORF_DISIR','medium','The female form of the fylgja (kynfylgja) overlaps conceptually with the protective dis; both are personal/familial tutelary female spirits, per Simek and Lindow.'),
 ('ENT_NORF_DISIR','aligned_with','ENT_NOR_NORNS','medium','The disir as fate-bound female collective overlap with the norns in their fate-determining function; aligned (functional) per Lindow.'),
 ('ENT_NORF_DISIR','aligned_with','ENT_NOR_VALKYRIES','medium','Disir overlap functionally with the valkyrjur as numinous female beings associated with death and protection; aligned per Simek/Lindow.'),
 ('ENT_NORF_DISIR','aligned_with','ENT_NOR_VANIR','low','The disablot fertility/ancestral cult and the figure of Freyja as Vanadis link the disir to the Vanir sphere; tentative functional alignment.'),
 ('ENT_NORF_LANDVAETTIR','aligned_with','ENT_NOR_DWARVES','low','Both landvaettir and dvergar are chthonic place-bound numina of the Norse landscape; tentative functional alignment of land/earth spirits.'),
 ('ENT_NORF_LANDVAETTIR','aligned_with','ENT_NOR_NERTHUS','low','The landvaettir, as tutelary spirits of land and fertility of place, sit in the same earth-numen sphere as the Germanic earth-goddess Nerthus; tentative thematic alignment.'),
 ('ENT_NORF_DRAUGR','opposes','ENT_NOR_EINHERJAR','low','The draugr (the unquiet, barrow-bound dead) stands as the negative counterpart to the honored battle-dead Einherjar received into Valhalla; thematic contrast in Norse conceptions of the dead.');
